class Solution:
    def isPerfectSquare(self, num: int) -> bool:
        low, high = 0, num
        ans = 0
        while low <= high:
            mid = (low + high) // 2
            if mid*mid <= num:
                ans = mid
                low = mid + 1
            else:
                high = mid - 1

        return ans * ans == num
